110	func (s *Store) DeleteUserSettings(ctx context.Context, delete *DeleteUserSetting) error {
111		existing, err := s.ListUserSettings(ctx, &FindUserSetting{
112			UserID: delete.UserID,
113			Key:    delete.Key,
114		})
115		if err != nil {
116			return err
117		}
118		if err := s.driver.DeleteUserSettings(ctx, delete); err != nil {
119			return err
120		}
121		for _, setting := range existing {
122			s.userSettingCache.Delete(ctx, getUserSettingCacheKey(setting.UserId, setting.Key.String()))
123		}
124		return nil
125	}
