367		oldWebhooks, err := s.GetUserWebhooks(ctx, userID)
368		if err != nil {
369			return err
370		}
371	
372		newWebhooks := make([]*storepb.WebhooksUserSetting_Webhook, 0, len(oldWebhooks))
373		for _, webhook := range oldWebhooks {
374			if webhookID != webhook.Id {
375				newWebhooks = append(newWebhooks, webhook)
376			}
377		}
378	
379		_, err = s.UpsertUserSetting(ctx, &storepb.UserSetting{
380			UserId: userID,
381			Key:    storepb.UserSetting_WEBHOOKS,
382			Value: &storepb.UserSetting_Webhooks{
383				Webhooks: &storepb.WebhooksUserSetting{
384					Webhooks: newWebhooks,
385				},
386			},
387		})
388	
389		return err
390	}
